    row_spans = spans(h, row_cuts)
    col_spans = spans(w, col_cuts)

    tiles = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            tiles.append([row[c0:c1] for row in grid[r0:r1]])

    n = len(tiles)
    if n == 1:
        return [row[:] for row in grid]

    def edge_match(a, b, horizontal):
        # Count occupied cells that line up across the adjoining tile edges.
        total = 0
        if horizontal:
            for r in range(len(a)):
                total += int(a[r][-1] not in (6, 7) and b[r][0] not in (6, 7))
        else:
            for c in range(len(a[0])):
                total += int(a[-1][c] not in (6, 7) and b[0][c] not in (6, 7))
        return total

    # Natural clockwise panel order is the tie-breaker.
    vertical_strip = len(col_spans) == 1 and len(row_spans) > 1
    horizontal_strip = len(row_spans) == 1 and len(col_spans) > 1

    best = None
    for horizontal in (True, False):
        if vertical_strip:
            baseline = list(reversed(range(n))) if horizontal else list(range(n))
        elif horizontal_strip:
            baseline = list(range(n)) if horizontal else list(range(n))
        else:
            baseline = list(range(n))

        # Exhaustively find an ordering with the most matching colored edge cells.
        if n <= 9:
            import itertools
            candidates = itertools.permutations(range(n))
        else:
            candidates = [tuple(baseline)]

        for order in candidates:
            score = sum(
                edge_match(tiles[order[i]], tiles[order[i + 1]], horizontal)
                for i in range(n - 1)
            )
            # Prefer clockwise orientation and its natural order in ties.
            orient_pref = (
                1 if ((vertical_strip and horizontal) or
                      (horizontal_strip and not horizontal) or
                      (not vertical_strip and not horizontal_strip and horizontal))
                else 0
            )
            baseline_pref = sum(order[i] == baseline[i] for i in range(n))
            key = (score, orient_pref, baseline_pref)
            if best is None or key > best[0]:
                best = (key, horizontal, list(order))

    _, horizontal, order = best
    sequence = [tiles[i] for i in order]

